  private fun mixText(name: String, value: Any?) {
    when (value) {
      is String -> mix(name, value.encodeToByteArray())
      is NodePath -> mix(name, value.path.encodeToByteArray())
      is List<*> -> value.forEach { mixText(name, it) }
      else -> mix(name, value)
    }
  }

